function drawMantineCelestialRay(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.4;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.04 * breathSin;
  const sX = 1.0 - 0.02 * breathSin;
  const by = Math.sin(breathPhase) * 3.5;

  const wingFlap = Math.sin(t * 2.8) * 4.5;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 32 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Đuôi
  ctx.fillStyle = '#1d4ed8';
  ctx.beginPath(); ctx.moveTo(8, by + 12); ctx.lineTo(34, by + 24); ctx.lineTo(18, by + 18); ctx.fill();
  ctx.fillStyle = '#e0e7ff';
  ctx.beginPath(); ctx.arc(34, by + 24, 4, 0, Math.PI * 2); ctx.fill();

  // 3. Cánh đuối trái & phải
  const wly = by + wingFlap;
  ctx.fillStyle = '#1d4ed8';
  ctx.beginPath(); ctx.moveTo(-6, by + 4); ctx.lineTo(-44, wly - 8); ctx.lineTo(-18, by + 16); ctx.fill();
  ctx.fillStyle = '#e0e7ff';
  ctx.beginPath(); ctx.moveTo(-8, by + 6); ctx.lineTo(-42, wly - 6); ctx.lineTo(-18, by + 14); ctx.fill();

  const wry = by - wingFlap;
  ctx.fillStyle = '#1d4ed8';
  ctx.beginPath(); ctx.moveTo(6, by + 4); ctx.lineTo(44, wry - 8); ctx.lineTo(18, by + 16); ctx.fill();
  ctx.fillStyle = '#e0e7ff';
  ctx.beginPath(); ctx.moveTo(8, by + 6); ctx.lineTo(42, wry - 6); ctx.lineTo(18, by + 14); ctx.fill();

  // 4. Remoraid
  ctx.fillStyle = '#64748b';
  ctx.beginPath(); ctx.roundRect(24, wry + 2, 10, 5, 2); ctx.fill();
  ctx.beginPath(); ctx.moveTo(34, wry + 4); ctx.lineTo(38, wry + 1); ctx.lineTo(38, wry + 7); ctx.fill();

  // 5. Thân
  ctx.fillStyle = '#1d4ed8';
  ctx.beginPath(); ctx.ellipse(0, by + 10, 22 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#e0e7ff';
  ctx.beginPath(); ctx.ellipse(0, by + 12, 19 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // 6. Sừng ăng-ten
  ctx.fillStyle = '#1d4ed8';
  ctx.beginPath(); ctx.roundRect(-14, by - 16, 5, 14, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-2,  by - 18, 5, 16, 2); ctx.fill();

  // 7. Mắt
  if (!blink) {
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.arc(-14, by + 2, 3, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(4,   by + 2, 3, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-15, by + 1, 1, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(3,   by + 1, 1, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-16, by + 2); ctx.lineTo(-12, by + 2); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(2,   by + 2); ctx.lineTo(6,   by + 2); ctx.stroke();
  }

  ctx.restore();
}
